// Replay only recorded actual history; no hypothetical moves, search or recommendation.
module.exports = history=>{
const cols="ABCDEFGHJ",board={};for(let y=1;y<=9;y++)for(const c of cols)board[c+y]=".";
const nb=p=>{const x=cols.indexOf(p[0]),y=+p[1];return [[x-1,y],[x+1,y],[x,y-1],[x,y+1]].filter(([a,b])=>a>=0&&a<9&&b>=1&&b<=9).map(([a,b])=>cols[a]+b);};
const group=p=>{const color=board[p],stones=[],liberties=new Set(),seen=new Set([p]),q=[p];while(q.length){const u=q.pop();stones.push(u);for(const v of nb(u)){if(board[v]===color&&!seen.has(v)){seen.add(v);q.push(v);}else if(board[v]===".")liberties.add(v);}}return {stones,liberties:[...liberties]};};
let ko=null,captures={X:0,O:0},moves=[],events=[],checks=[];
const actual=(color,point)=>{const number=moves.length+1;if(color!==(number%2?"X":"O"))throw Error("wrong color "+number);moves.push({number,color:color==="X"?"B":"W",point});if(point==="pass"){ko=null;return;}
if(board[point]!==".")throw Error("occupied "+number);if(point===ko)throw Error("ko "+number);board[point]=color;
let removed=[],seen=new Set();for(const p of nb(point))if(board[p]!=="."&&board[p]!==color&&!seen.has(p)){const g=group(p);g.stones.forEach(x=>seen.add(x));if(!g.liberties.length){removed.push(...g.stones);g.stones.forEach(x=>board[x]=".");}}
const own=group(point);if(!own.liberties.length)throw Error("suicide "+number);captures[color]+=removed.length;ko=removed.length===1&&own.stones.length===1&&own.liberties.length===1?removed[0]:null;if(removed.length)events.push({number,color:color==="X"?"B":"W",point,removed,ownLiberties:own.liberties,ko});
};
for(const [i,h] of history.entries()){const s=h.response.content.filter(x=>x.type==="text").map(x=>x.text).join("\n");
if(h.kind==="choose_opponent"){const m=s.match(/It plays first: ([A-HJ][1-9]|pass)/);if(!m)throw Error("missing opening");actual("X",m[1]);}
if(h.kind==="play"){const u=s.match(/You played ([A-HJ][1-9])\.|You passed\./),v=s.match(/Your opponent played ([A-HJ][1-9])\.|Your opponent passed\./);if(!u||!v)throw Error("missing moves "+i);actual("O",u[1]||"pass");actual("X",v[1]||"pass");}
const shown={};for(const line of s.split("\n")){const m=line.match(/^\s*([1-9])\s+([XO.](?:\s+[XO.]){8})\s+[1-9]\s*$/);if(m)m[2].split(/\s+/).forEach((x,j)=>shown[cols[j]+m[1]]=x);}
if(Object.keys(shown).length!==81)throw Error("board parse "+i);for(const p in board)if(board[p]!==shown[p])throw Error("board mismatch "+i+" "+p);
const cap=s.match(/Captured by Black: (\d+); by White: (\d+)/),marker=s.match(/Ko point: ([^.]+)\./),num=s.match(/Move number: (\d+)/);if(!cap||+cap[1]!==captures.X||+cap[2]!==captures.O)throw Error("captures "+i);if(!marker||(marker[1]==="none"?null:marker[1])!==ko)throw Error("ko mismatch "+i);if(!num||+num[1]!==moves.length+1)throw Error("move number "+i);
checks.push({historyIndex:i,actualMoves:moves.length,fullBoard:true,captures:{...captures},ko});
}
return {moves,events,checks,totalMoves:moves.length,fullBoardsChecked:checks.length,finalCaptures:captures,finalBoard:board,finalStones:{Black:Object.values(board).filter(x=>x==="X").length,White:Object.values(board).filter(x=>x==="O").length},noRefusedMoves:true};
};
